/* ============================================================
   TEST PAGE 4 — THE PERFUMERS' GRAPH (2026-11-06, in place of "The Scent
   Landscape").

   The owner: "replace tp4 with another iteration of the perfumers page,
   and this one should be something like images 5 and 6. It should have a
   table where you can select the perfumers and then it would take you to a
   node, which would have subnodes of houses, then further subnodes of
   perfumes." Image 5: a network of dark specks on a pale grey, joined in
   hairlines, clustered, framed by the corners of a camera — OBJECT and its
   name at the top, the word looked at spelled down the left with where
   each letter stands, STAGE 5: LETTERS at the foot, TOTAL at the bottom
   right, a dashed ring turning at the bottom left. Image 6: a graph view —
   a round field of nodes, the busiest with fans of fine lines.

   Here: every PERFUMER a node, every one of its HOUSES a node joined to it,
   every PERFUME a speck in a fan round its house; a house more than one
   perfumer made for is joined across to its other perfumers. THE TABLE on
   the right lists the perfumers (sortable, searchable); a row pressed takes
   the camera to its node, and its houses come out round it, named; a house
   pressed, its perfumes, named; a perfume pressed spells itself down the
   left, letter by letter, as image 5's word does. The stages say how deep
   you are: 1 PERFUMERS, 2 HOUSES, 3 PERFUMES, 4 LETTERS. The wheel, a drag
   and the keys move about; the ground is image 5's grey or image 6's dark.

   A snapshot of the site's Perfumers ledger, written in above: nothing on
   the site reads this page, and it reads nothing of the site.
   ============================================================ */
(function () {
  "use strict";
  const STILL = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  function rng(seed) { let s = seed >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }
  const cmp = (a, b) => String(a).localeCompare(String(b), "en", { sensitivity: "base" });
  const fold = (t) => String(t).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  const el = (s) => document.querySelector(s);

  // ---- THE DATA, as a graph -------------------------------------------------
  const D = DATA;
  const CREDIT = ["named by a source", "the house's perfumer", "perfumer not found"];
  const PER = D.perfumers.map((p, i) => Object.assign({}, p, { i, list: [], houses: new Map(), none: p.id === "not-found" }));
  const HOU = D.houses;
  D.perfumes.forEach((r) => r[1].forEach((q) => {
    const e = { n: r[0], q, c: r[2], y: r[3], h: r[4], k: r[5], s: r[6], who: r[1] };
    PER[q].list.push(e);
    if (!PER[q].houses.has(r[4])) PER[q].houses.set(r[4], []);
    PER[q].houses.get(r[4]).push(e);
  }));
  const ORDER = PER.slice().sort((a, b) => (a.none - b.none) || cmp(a.sort, b.sort));
  ORDER.forEach((p, k) => { p.k = k; p.name2 = p.none ? "Perfumer not found" : p.name; });
  const TOTAL = PER.reduce((n, p) => n + p.list.length, 0);
  // the nodes: perfumers, their houses (one for each perfumer it is made
  // with), the perfumes; and the links between them
  const nodes = [], links = [];
  const R = rng(20261106);
  ORDER.forEach((p) => {
    const pn = { kind: "per", p, name: p.name2, x: 0, y: 0, r: 0 };
    p.node = pn; nodes.push(pn);
    pn.houses = [];
    Array.from(p.houses.entries()).sort((a, b) => cmp(HOU[a[0]].name, HOU[b[0]].name)).forEach(([h, list], j) => {
      const hn = { kind: "house", p, h, name: HOU[h].name, list, x: 0, y: 0, j, par: pn, leaves: [] };
      nodes.push(hn); pn.houses.push(hn); links.push({ a: pn, b: hn, k: 1 });
      list.slice().sort((a, b) => (a.y || 9999) - (b.y || 9999) || cmp(a.n, b.n)).forEach((e, m) => {
        const ln = { kind: "perfume", p, h, e, name: e.n, x: 0, y: 0, m, par: hn };
        nodes.push(ln); hn.leaves.push(ln); links.push({ a: hn, b: ln, k: 2 });
      });
    });
  });
  // a house made for by more than one perfumer, joined across
  const byHouse = new Map();
  nodes.forEach((n) => { if (n.kind === "house") { if (!byHouse.has(n.h)) byHouse.set(n.h, []); byHouse.get(n.h).push(n); } });
  byHouse.forEach((list) => { for (let i = 1; i < list.length; i++) links.push({ a: list[0], b: list[i], k: 3 }); });

  // ---- THE LAYOUT: the perfumers packed in a round field, each its houses
  // round it and each house its perfumes in a fan (image 6) — worked out once
  function layGraph() {
    // each perfumer a territory as big as its perfumes
    ORDER.forEach((p) => { p.node.rT = 34 + Math.sqrt(p.list.length) * 21; });
    // laid on a spiral, the biggest at the middle, then pressed together
    const big = ORDER.slice().sort((a, b) => b.list.length - a.list.length);
    big.forEach((p, i) => { const a = i * 2.39996, r = Math.sqrt(i) * 70; p.node.x = Math.cos(a) * r; p.node.y = Math.sin(a) * r; });
    for (let it = 0; it < 400; it++) {
      for (let i = 0; i < big.length; i++) for (let j = i + 1; j < big.length; j++) {
        const a = big[i].node, b = big[j].node;
        let dx = b.x - a.x, dy = b.y - a.y, d = Math.hypot(dx, dy) || 0.01;
        const want = a.rT + b.rT + 14;
        if (d < want) { const s = (want - d) / 2 / d; a.x -= dx * s; a.y -= dy * s; b.x += dx * s; b.y += dy * s; }
      }
      // all of them drawn towards the middle, gently
      big.forEach((p) => { p.node.x *= 0.985; p.node.y *= 0.985; });
    }
    // the houses round their perfumer, the perfumes in a fan round each house
    ORDER.forEach((p) => {
      const pn = p.node, hs = pn.houses, n = hs.length;
      const out = Math.atan2(pn.y, pn.x) || R() * TAU;
      hs.forEach((hn, j) => {
        const a = n === 1 ? out + 0.6 : out + (j / n) * TAU + 0.4;
        const share = hn.list.length / p.list.length;
        const d = n === 1 ? pn.rT * 0.36 : pn.rT * (0.42 + 0.1 * (1 - share));
        hn.x = pn.x + Math.cos(a) * d; hn.y = pn.y + Math.sin(a) * d; hn.a = a;
        const m = hn.leaves.length;
        const reach = 14 + Math.sqrt(m) * 9;
        // a full ring for a big house, a fan pointing away for a small one
        const spread = m > 14 ? TAU : Math.min(TAU, 0.5 + m * 0.42);
        hn.leaves.forEach((ln, k) => {
          const aa = m > 14 ? (k / m) * TAU : a + (m === 1 ? 0 : (k / (m - 1) - 0.5) * spread);
          const rr = reach * (0.72 + 0.28 * ((k * 7) % 5) / 4);
          ln.x = hn.x + Math.cos(aa) * rr; ln.y = hn.y + Math.sin(aa) * rr;
          ln.ox = ln.x; ln.oy = ln.y; ln.ph = R() * TAU;
        });
      });
    });
    // the field centred on itself, and its extent
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    nodes.forEach((n) => { x0 = Math.min(x0, n.x); x1 = Math.max(x1, n.x); y0 = Math.min(y0, n.y); y1 = Math.max(y1, n.y); });
    const mx = (x0 + x1) / 2, my = (y0 + y1) / 2;
    nodes.forEach((n) => { n.x -= mx; n.y -= my; if (n.ox !== undefined) { n.ox -= mx; n.oy -= my; } });
    field.rx = (x1 - x0) / 2 + 40; field.ry = (y1 - y0) / 2 + 40;
    field.r = Math.max(field.rx, field.ry);
  }
  const field = { r: 600 };

  // ---- THE PAGE ------------------------------------------------------------
  const cv = el(".t4-scene"), ctx = cv.getContext("2d");
  const tip = el(".t4-tip");
  let W = 0, H = 0, DPR = 1, phone = false;
  const cam = { x: 0, y: 0, z: 1 }, goal = { x: 0, y: 0, z: 1 };
  let fitZ = 1, dark = false;
  try { dark = localStorage.getItem("t4-ground") === "dark"; } catch (e) { /* no storage */ }
  const room = () => {
    const t = el(".t4-table");
    const right = !phone && t ? t.getBoundingClientRect().left : W;
    return { x0: phone ? 0 : 250, x1: right - 10, y0: phone ? 70 : 60, y1: phone ? H * 0.56 : H - 60 };
  };
  function resize() {
    W = window.innerWidth; H = window.innerHeight;
    phone = W < 760;
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
    cv.style.width = W + "px"; cv.style.height = H + "px";
    const rm = room();
    fitZ = Math.min((rm.x1 - rm.x0) / (2 * field.rx), (rm.y1 - rm.y0) / (2 * field.ry)) * 0.96;
    groundImg = null;
    aimAt(focus, true);
  }
  let RM = null;
  const SX = (x) => (x - cam.x) * cam.z + RM.cx, SY = (y) => (y - cam.y) * cam.z + RM.cy;

  // ---- WHAT IS IN FOCUS ----------------------------------------------------
  // null: the whole field (stage 1); a perfumer (2); a house (3); a perfume (4)
  let focus = null;
  const stageOf = (f) => (!f ? 1 : f.kind === "per" ? 2 : f.kind === "house" ? 3 : 4);
  const STAGES = ["PERFUMERS", "HOUSES", "PERFUMES", "LETTERS"];
  function aimAt(f, jump) {
    if (!f) { goal.x = 0; goal.y = 0; goal.z = fitZ; }
    else if (f.kind === "per") { goal.x = f.x; goal.y = f.y; goal.z = clamp(Math.min(room().x1 - room().x0, room().y1 - room().y0) / (2 * f.rT * 1.15), fitZ, 6); }
    else if (f.kind === "house") { const r = 24 + Math.sqrt(f.leaves.length) * 12; goal.x = f.x; goal.y = f.y; goal.z = clamp(Math.min(room().x1 - room().x0, room().y1 - room().y0) / (2 * r * 1.7), fitZ, 9); }
    else { goal.x = f.x; goal.y = f.y; goal.z = Math.max(goal.z, Math.min(9, fitZ * 6)); }
    if (jump || STILL) Object.assign(cam, goal);
    kick();
  }
  function setFocus(f) {
    focus = f;
    aimAt(f);
    writeReadout();
    syncTable();
    kick();
  }
  const isIn = (n, f) => {
    if (!f) return true;
    if (f.kind === "per") return n.p === f.p;
    if (f.kind === "house") return n === f || n.par === f || n === f.par;
    return n === f || n === f.par || n === f.par.par;
  };

  // ---- THE READOUT: the word looked at, letter by letter (image 5) -----------
  function writeReadout() {
    const st = stageOf(focus);
    el("[data-v=stage]").textContent = "STAGE " + st + ": " + STAGES[st - 1];
    const within = !focus ? TOTAL : focus.kind === "per" ? focus.p.list.length : focus.kind === "house" ? focus.leaves.length : 1;
    el("[data-v=total]").textContent = "TOTAL: " + within.toLocaleString("en").replace(/,/g, " ");
    el("[data-v=object]").textContent = !focus ? "THE TASTE OF ALDEHYDES" : focus.kind === "per" ? focus.p.name2.toUpperCase() : focus.kind === "house" ? HOU[focus.h].name.toUpperCase() : (HOU[focus.h].name + " · " + focus.p.name2).toUpperCase();
    el("[data-v=quote]").textContent = !focus ? "“PERFUMERS”" : focus.kind === "per" ? "“" + focus.houses.length + (focus.houses.length === 1 ? " HOUSE" : " HOUSES") + "”" : focus.kind === "house" ? "“" + focus.leaves.length + " PERFUMES”" : "“" + focus.e.n.toUpperCase() + "”";
    const rd = el(".t4-read");
    if (!focus) {
      rd.innerHTML = '<p class="t4-word">«perfumers»</p><p class="t4-at">[' + ORDER.length + " perfumers, " + nodes.filter((n) => n.kind === "house").length + " houses, " + TOTAL + " perfumes]</p>" +
        '<p class="t4-say">Choose a perfumer in the table, or press a node.</p>';
      return;
    }
    const pk = focus.p.k + 1, hk = focus.kind === "per" ? 0 : (focus.kind === "house" ? focus.j : focus.par.j) + 1, ek = focus.kind === "perfume" ? focus.m + 1 : 0;
    const word = focus.kind === "per" ? focus.p.name2 : focus.kind === "house" ? HOU[focus.h].name : focus.e.n;
    const at = focus.kind === "per" ? "[Perfumer " + pk + "]" : focus.kind === "house" ? "[Perfumer " + pk + ", House " + hk + "]" : "[Perfumer " + pk + ", House " + hk + ", Perfume " + ek + "]";
    const letters = Array.from(word.replace(/\s+/g, "")).slice(0, 18);
    let h = '<p class="t4-word">«' + esc(word.toLowerCase()) + "»</p><p class=\"t4-at\">" + at + "</p><ol class=\"t4-letters\">";
    letters.forEach((ch, i) => { h += "<li><b>" + esc(ch.toUpperCase()) + "</b><span>{" + [pk, hk, ek, i].join("; ") + "}</span></li>"; });
    h += "</ol>";
    if (focus.kind === "perfume") {
      const e = focus.e;
      h += '<p class="t4-say">' + esc(e.who.map((q) => PER[q].name2).join(" & ")) + " — " + CREDIT[e.c] + " · " + (e.y || "year not found") + (e.s.length ? " · " + e.s.map((i) => esc(D.sources[i])).join(", ") : "") + "</p>";
    } else if (focus.kind === "house") {
      h += '<p class="t4-say">' + esc(HOU[focus.h].about || HOU[focus.h].name) + "</p>";
    } else if (focus.p.about.length) h += '<p class="t4-say">' + esc(focus.p.about[0]) + "</p>";
    rd.innerHTML = h;
  }

  // ---- THE TABLE: the perfumers, sortable and searchable ---------------------
  const tbody = el(".t4-table tbody");
  let sortBy = "name", sortDir = 1;
  function rowsHtml() {
    const q = fold(el(".t4-find").value.trim());
    const list = ORDER.filter((p) => !q || fold(p.name2).includes(q) || Array.from(p.houses.keys()).some((h) => fold(HOU[h].name).includes(q)) || p.list.some((e) => fold(e.n).includes(q)));
    const val = (p) => sortBy === "name" ? (p.none ? "￿" : p.sort) : sortBy === "houses" ? p.houses.size : sortBy === "perfumes" ? p.list.length : (p.list.map((e) => e.y).filter(Boolean).sort()[0] || 9999);
    list.sort((a, b) => { const x = val(a), y = val(b); return (typeof x === "number" ? x - y : cmp(x, y)) * sortDir || a.k - b.k; });
    return list.map((p) => {
      const ys = p.list.map((e) => e.y).filter(Boolean);
      const yr = ys.length ? Math.min(...ys) + (Math.max(...ys) !== Math.min(...ys) ? "–" + String(Math.max(...ys)).slice(2) : "") : "—";
      return '<tr data-per="' + p.i + '"><td>' + String(p.k + 1).padStart(2, "0") + '</td><th scope="row"><button type="button">' + esc(p.name2) + "</button></th><td>" + p.houses.size + "</td><td>" + p.list.length + "</td><td>" + yr + "</td></tr>";
    }).join("");
  }
  function fillTable() { tbody.innerHTML = rowsHtml(); syncTable(); }
  function syncTable() {
    tbody.querySelectorAll("tr").forEach((tr) => {
      const on = focus && +tr.dataset.per === focus.p.i;
      tr.classList.toggle("is-on", !!on);
      if (on && !phone) { const b = el(".t4-table-scroll"); const r = tr.getBoundingClientRect(), s = b.getBoundingClientRect(); if (r.top < s.top + 30 || r.bottom > s.bottom - 10) b.scrollTop += r.top - s.top - 60; }
    });
    const sub = el(".t4-sub");
    if (!focus) { sub.hidden = true; return; }
    const pn = focus.p.node;
    sub.hidden = false;
    sub.innerHTML = '<p class="t4-sub-head">' + esc(focus.p.name2) + " · houses</p><ul>" + pn.houses.map((hn) =>
      '<li><button type="button" data-house="' + nodes.indexOf(hn) + '" class="' + (focus === hn || (focus.par === hn) ? "is-on" : "") + '">' + esc(hn.name) + "<i>" + hn.leaves.length + "</i></button>" +
      (focus === hn || focus.par === hn ? "<ul>" + hn.leaves.map((ln) => '<li><button type="button" data-leaf="' + nodes.indexOf(ln) + '" class="' + (focus === ln ? "is-on" : "") + '">' + esc(ln.name) + "<i>" + (ln.e.y || "—") + "</i></button></li>").join("") + "</ul>" : "") + "</li>").join("") + "</ul>";
  }
  tbody.addEventListener("click", (ev) => { const tr = ev.target.closest("tr"); if (!tr) return; const p = PER[+tr.dataset.per]; setFocus(focus && focus.kind === "per" && focus.p === p ? null : p.node); if (phone) openTable(false); });
  tbody.addEventListener("pointerover", (ev) => { const tr = ev.target.closest("tr"); if (tr) { hover = PER[+tr.dataset.per].node; kick(); } });
  tbody.addEventListener("pointerleave", () => { hover = null; kick(); });
  el(".t4-sub").addEventListener("click", (ev) => {
    const h = ev.target.closest("[data-house]"); if (h) { setFocus(nodes[+h.dataset.house]); return; }
    const l = ev.target.closest("[data-leaf]"); if (l) setFocus(nodes[+l.dataset.leaf]);
  });
  el(".t4-table thead").addEventListener("click", (ev) => {
    const th = ev.target.closest("[data-sort]"); if (!th) return;
    if (sortBy === th.dataset.sort) sortDir *= -1; else { sortBy = th.dataset.sort; sortDir = sortBy === "name" ? 1 : -1; }
    el(".t4-table thead").querySelectorAll("[data-sort]").forEach((x) => x.setAttribute("aria-sort", x === th ? (sortDir > 0 ? "ascending" : "descending") : "none"));
    fillTable();
  });
  el(".t4-find").addEventListener("input", fillTable);
  function openTable(on) { el(".t4-table").classList.toggle("is-open", on); el(".t4-table-toggle").setAttribute("aria-expanded", on ? "true" : "false"); }
  el(".t4-table-toggle").addEventListener("click", () => openTable(!el(".t4-table").classList.contains("is-open")));

  // ---- THE GROUND: image 5's grey, or image 6's dark --------------------------
  let groundImg = null;
  function setGround(d) {
    dark = d;
    document.body.classList.toggle("is-dark", dark);
    document.querySelectorAll(".t4-ground button").forEach((b) => b.setAttribute("aria-pressed", (b.dataset.ground === "dark") === dark ? "true" : "false"));
    try { localStorage.setItem("t4-ground", dark ? "dark" : "grey"); } catch (e) { /* no storage */ }
    groundImg = null; kick();
  }
  document.querySelectorAll(".t4-ground button").forEach((b) => b.addEventListener("click", () => setGround(b.dataset.ground === "dark")));
  function ground() {
    const c = document.createElement("canvas");
    c.width = cv.width; c.height = cv.height;
    const x = c.getContext("2d");
    x.scale(DPR, DPR);
    if (dark) { x.fillStyle = "#1c1c1d"; x.fillRect(0, 0, W, H); }
    else {
      const g = x.createRadialGradient(W * 0.45, H * 0.45, 0, W * 0.45, H * 0.5, Math.max(W, H) * 0.75);
      g.addColorStop(0, "#e6e7e9"); g.addColorStop(0.55, "#c9cbce"); g.addColorStop(1, "#9ea1a6");
      x.fillStyle = g; x.fillRect(0, 0, W, H);
    }
    return c;
  }

  // ---- DRAWING ------------------------------------------------------------
  let hover = null;
  const signals = [];
  let sigNext = 0;
  function draw(t, intro) {
    RM = room(); RM.cx = (RM.x0 + RM.x1) / 2; RM.cy = (RM.y0 + RM.y1) / 2;
    if (!groundImg) groundImg = ground();
    const c = ctx;
    c.setTransform(1, 0, 0, 1, 0, 0);
    c.drawImage(groundImg, 0, 0);
    c.setTransform(DPR, 0, 0, DPR, 0, 0);
    const ink = dark ? "220,220,218" : "20,20,24";
    const INK = "rgb(" + ink + ")";
    const z = cam.z, f = focus, h = hover;
    // the leaves breathe a little, so the field is never quite still
    const wob = STILL ? 0 : 1;
    nodes.forEach((n) => {
      if (n.kind === "perfume") { n.x = n.ox + wob * Math.sin(t * 0.7 + n.ph) * 0.8; n.y = n.oy + wob * Math.cos(t * 0.6 + n.ph) * 0.8; }
      n.sx = SX(n.x); n.sy = SY(n.y);
    });
    const onScreen = (n) => n.sx > -40 && n.sx < W + 40 && n.sy > -40 && n.sy < H + 40;
    const grow = (n) => STILL ? 1 : ease(clamp(intro * 1.8 - (Math.hypot(n.x, n.y) / field.r) * 0.8, 0, 1));
    // the links: faint, what is in focus darker; the cross links dashed
    const lv = [new Path2D(), new Path2D(), new Path2D()];
    let cross = new Path2D();
    links.forEach((l) => {
      const ga = grow(l.b);
      if (ga <= 0) return;
      if (!onScreen(l.a) && !onScreen(l.b)) return;
      const inF = !f || (isIn(l.a, f) && isIn(l.b, f));
      const hot = h && isIn(l.a, h) && isIn(l.b, h);
      const k = hot || (f && inF) ? 2 : inF ? 1 : 0;
      const p = l.k === 3 ? cross : lv[k];
      p.moveTo(l.a.sx, l.a.sy); p.lineTo(lerp(l.a.sx, l.b.sx, ga), lerp(l.a.sy, l.b.sy, ga));
    });
    c.strokeStyle = INK; c.lineWidth = 0.6;
    c.globalAlpha = f ? 0.06 : 0.22; c.stroke(lv[0]);
    c.globalAlpha = f ? 0.2 : 0.32; c.stroke(lv[1]);
    c.globalAlpha = 0.6; c.lineWidth = 0.8; c.stroke(lv[2]);
    c.setLineDash([3, 4]); c.globalAlpha = 0.3; c.lineWidth = 0.6; c.stroke(cross); c.setLineDash([]);
    // signals running out along the links
    if (!STILL && intro >= 1) {
      if (t > sigNext && signals.length < 30) {
        const pool = f ? links.filter((l) => isIn(l.a, f) && isIn(l.b, f)) : links;
        const l = pool[Math.floor(Math.random() * pool.length)];
        if (l) signals.push({ l, t0: t, dur: 0.9 + Math.random() * 0.9 });
        sigNext = t + 0.05 + Math.random() * 0.12;
      }
      c.fillStyle = INK;
      for (let i = signals.length - 1; i >= 0; i--) {
        const s = signals[i], u = (t - s.t0) / s.dur;
        if (u >= 1) { signals.splice(i, 1); continue; }
        const x = lerp(s.l.a.sx, s.l.b.sx, ease(u)), y = lerp(s.l.a.sy, s.l.b.sy, ease(u));
        c.globalAlpha = Math.sin(Math.PI * u) * 0.8;
        c.beginPath(); c.arc(x, y, 1.4, 0, TAU); c.fill();
      }
    }
    // the nodes: a perfume a speck, a house a dot, a perfumer a ring round a dot
    const dots = [new Path2D(), new Path2D()];
    nodes.forEach((n) => {
      if (!onScreen(n)) return;
      const ga = grow(n);
      if (ga <= 0.05) return;
      const inF = !f || isIn(n, f);
      const r = (n.kind === "perfume" ? 1.6 : n.kind === "house" ? 3 : 4.4) * clamp(Math.sqrt(z / fitZ), 1, 2.6) * ga;
      const p = dots[inF ? 1 : 0];
      p.moveTo(n.sx + r, n.sy); p.arc(n.sx, n.sy, r, 0, TAU);
    });
    c.fillStyle = INK;
    c.globalAlpha = f ? 0.18 : 0.85; c.fill(dots[0]);
    c.globalAlpha = 0.92; c.fill(dots[1]);
    // perfumers' rings, the clusters' halos
    nodes.forEach((n) => {
      if (n.kind !== "per" || !onScreen(n)) return;
      const inF = !f || isIn(n, f);
      c.globalAlpha = (inF ? 0.5 : 0.12) * grow(n);
      c.strokeStyle = INK; c.lineWidth = 0.8;
      const r = 8 * clamp(Math.sqrt(z / fitZ), 1, 2.6);
      c.beginPath(); c.arc(n.sx, n.sy, r, 0, TAU); c.stroke();
    });
    // the names: the perfumers always, a focus's houses and perfumes, what the hand is on
    c.textBaseline = "middle";
    const label = (n, size, weight, alpha, dx) => {
      c.font = weight + " " + size + 'px "IBM Plex Mono", ui-monospace, monospace';
      c.globalAlpha = alpha; c.fillStyle = INK; c.textAlign = "left";
      c.fillText(n.kind === "per" ? n.name.toUpperCase() : n.name, n.sx + (dx || 8), n.sy);
    };
    nodes.forEach((n) => {
      if (!onScreen(n)) return;
      const inF = f && isIn(n, f);
      if (n.kind === "per") label(n, phone ? 8.5 : 9.5, 500, (f ? (inF ? 0.95 : 0.25) : 0.8) * grow(n), 12);
      else if (n.kind === "house" && (inF || z > fitZ * 2.4)) label(n, phone ? 8 : 9, 500, inF ? 0.9 : 0.45, 7);
      else if (n.kind === "perfume" && ((f && f.kind !== "per" && inF) || z > fitZ * 5.5)) label(n, phone ? 7.5 : 8.5, 400, inF ? 0.85 : 0.4, 5);
    });
    // what the hand is on, and what is in focus: a ring, its name
    for (const n of [f, h]) {
      if (!n) continue;
      c.globalAlpha = 1; c.strokeStyle = INK; c.lineWidth = 1;
      c.beginPath(); c.arc(n.sx, n.sy, n.kind === "per" ? 14 : 9, 0, TAU); c.stroke();
      if (n === h && n !== f) label(n, 10, 500, 1, 14);
    }
    c.globalAlpha = 1;
  }

  // ---- THE HAND: the wheel zooms, a drag moves, a press chooses -------------
  function nodeAt(x, y) {
    let best = null, bd = phone ? 16 : 10;
    for (const n of nodes) { const d = Math.hypot(n.sx - x, n.sy - y) - (n.kind === "per" ? 6 : n.kind === "house" ? 3 : 0); if (d < bd) { bd = d; best = n; } }
    return best;
  }
  let drag = null;
  cv.addEventListener("pointerdown", (ev) => { drag = { x: ev.clientX, y: ev.clientY, cx: goal.x, cy: goal.y, moved: false }; cv.setPointerCapture(ev.pointerId); });
  cv.addEventListener("pointermove", (ev) => {
    if (drag) {
      const dx = ev.clientX - drag.x, dy = ev.clientY - drag.y;
      if (Math.hypot(dx, dy) > 6) drag.moved = true;
      if (drag.moved) { goal.x = drag.cx - dx / cam.z; goal.y = drag.cy - dy / cam.z; cam.x = goal.x; cam.y = goal.y; kick(); }
      return;
    }
    if (ev.pointerType === "touch") return;
    const n = nodeAt(ev.clientX, ev.clientY);
    if (n !== hover) { hover = n; kick(); }
    if (n) {
      const hs = n.kind === "per" ? n.houses.length : 0;
      tip.innerHTML = "<b>" + esc(n.name) + "</b><span>" + (n.kind === "per" ? "Perfumer · " + n.p.list.length + " perfumes · " + hs + (hs === 1 ? " house" : " houses")
        : n.kind === "house" ? "House · " + n.leaves.length + " perfumes by " + esc(n.p.name2) : "Perfume · " + esc(HOU[n.h].name) + " · " + (n.e.y || "year not found")) + "</span>";
      tip.hidden = false;
      tip.style.transform = "translate(" + Math.round(Math.min(W - 260, ev.clientX + 14)) + "px," + Math.round(Math.min(H - 60, ev.clientY + 14)) + "px)";
    } else tip.hidden = true;
    cv.style.cursor = n ? "pointer" : "grab";
  });
  cv.addEventListener("pointerup", (ev) => {
    const d = drag; drag = null;
    if (!d || d.moved) return;
    const n = nodeAt(ev.clientX, ev.clientY);
    if (n) setFocus(n === focus ? (n.kind === "per" ? null : n.kind === "house" ? n.par : n.par) : n);
  });
  cv.addEventListener("pointerleave", () => { hover = null; tip.hidden = true; kick(); });
  cv.addEventListener("wheel", (ev) => {
    ev.preventDefault();
    const k = Math.exp(-ev.deltaY * 0.0015);
    const nz = clamp(goal.z * k, fitZ * 0.7, fitZ * 14);
    // towards the hand
    const mx = (ev.clientX - RM.cx) / goal.z + goal.x, my = (ev.clientY - RM.cy) / goal.z + goal.y;
    goal.x = mx - (ev.clientX - RM.cx) / nz; goal.y = my - (ev.clientY - RM.cy) / nz;
    goal.z = nz;
    kick();
  }, { passive: false });
  document.addEventListener("keydown", (ev) => {
    if (ev.target && ev.target.matches && ev.target.matches("input")) return;
    if (ev.key === "Escape") { ev.preventDefault(); setFocus(!focus ? null : focus.kind === "per" ? null : focus.par); }
    else if (ev.key === "+" || ev.key === "=") { goal.z = Math.min(goal.z * 1.4, fitZ * 14); kick(); }
    else if (ev.key === "-") { goal.z = Math.max(goal.z / 1.4, fitZ * 0.7); kick(); }
    else if (ev.key === "0") { setFocus(null); }
  });
  el(".t4-up").addEventListener("click", () => setFocus(!focus ? null : focus.kind === "per" ? null : focus.par));
  el(".t4-fit").addEventListener("click", () => setFocus(null));

  // ---- THE CLOCK -------------------------------------------------------------
  let raf = 0, last = 0, clock = 0, t0 = -1;
  const INTRO_MS = 2000;
  function frame(now) {
    raf = 0;
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    if (!STILL) clock += dt;
    if (t0 < 0) t0 = now;
    const intro = STILL ? 1 : clamp((now - t0) / INTRO_MS, 0, 1);
    const k = STILL ? 1 : 1 - Math.exp(-dt * 4.5);
    cam.x += (goal.x - cam.x) * k; cam.y += (goal.y - cam.y) * k; cam.z *= Math.exp((Math.log(goal.z) - Math.log(cam.z)) * k);
    draw(clock, intro);
    el(".t4-zoom").textContent = Math.round((cam.z / fitZ) * 100) + "%";
    if (!STILL && !document.hidden) raf = requestAnimationFrame(frame);
    else last = 0;
  }
  function kick() { if (!raf) raf = requestAnimationFrame(frame); }
  document.addEventListener("visibilitychange", () => { if (!document.hidden) { last = 0; kick(); } });
  let rq = 0;
  window.addEventListener("resize", () => { if (rq) return; rq = requestAnimationFrame(() => { rq = 0; resize(); kick(); }); });
  if (STILL) ["click", "keydown", "wheel", "pointermove", "input"].forEach((e) => document.addEventListener(e, () => requestAnimationFrame(frame)));

  // ---- BEGIN -----------------------------------------------------------------
  layGraph();
  setGround(dark);
  fillTable();
  resize();
  RM = room(); RM.cx = (RM.x0 + RM.x1) / 2; RM.cy = (RM.y0 + RM.y1) / 2;
  writeReadout();
  kick();
  window.TestPage4 = {
    nodes: () => ({ perfumers: nodes.filter((n) => n.kind === "per").length, houses: nodes.filter((n) => n.kind === "house").length, perfumes: nodes.filter((n) => n.kind === "perfume").length }),
    focus: () => (focus ? { kind: focus.kind, name: focus.name, stage: stageOf(focus) } : { kind: null, stage: 1 }),
    cam: () => Object.assign({}, cam, { fit: fitZ }),
    pointOf: (name) => { const n = nodes.find((x) => x.name === name); return n ? { x: n.sx, y: n.sy } : null; },
    choose: (name) => { const n = nodes.find((x) => x.name === name); setFocus(n || null); },
  };
})();
